  "〜以外（は）": { vi: "ngoại trừ ~ / ngoài ~ ra", id: "kecuali ~", tl: "maliban sa ~", my: "~ မှလွဲ၍", zh: "除了~以外", ne: "~ बाहेक", km: "លើកលែងតែ ~", mn: "~-с бусад", th: "ยกเว้น ~ / นอกจาก ~", si: "~ හැර" },
